"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["70583"],{1573(e,t,o){o.d(t,{Ay:()=>s,RM:()=>a});var n=o(74848),i=o(28453);let a=[];function r(e){let t={blockquote:"blockquote",h1:"h1",header:"header",p:"p",...(0,i.R)(),...e.components};return(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(t.header,{children:(0,n.jsx)(t.h1,{id:"the-great-savior--a-savior-more-savior-than-the-savior-himself",children:"The Great Savior \u2014 A Savior More Savior Than the Savior Himself!"})}),"\n",(0,n.jsxs)(t.blockquote,{children:["\n",(0,n.jsx)(t.p,{children:"2006/4/18 21:29:10"}),"\n"]}),"\n",(0,n.jsx)(t.p,{children:'In Western society \u2014 particularly in Christianized Western society \u2014 a so-called "Great Savior" does not exist. What they have instead is the Messiah, the Savior. The biggest difference between the Great Savior and the Messiah is: the former is human, the latter is divine. For Western society, which believes in or advocates human equality, no person can replace God \u2014 therefore there naturally can be no human Great Savior. This is quite obvious within Western logic. For Chinese society, there is essentially no concept of divinity. Chinese gods are basically humans: an old man riding an ox became divine; a man wielding a great blade has been deified for two thousand years. That\'s the Chinese way. In Chinese society, since there are no gods, there is no Messiah \u2014 hence the Great Savior.'}),"\n",(0,n.jsx)(t.p,{children:'The Chinese belief in a Great Savior didn\'t start yesterday \u2014 it goes back probably two thousand years before Confucius. Back then, the Great Savior had a common name: the Sage. From the Three Sovereigns and Five Emperors onward, this game continued throughout Chinese history. The Great Savior also has a common literary image \u2014 the so-called North Star (Polaris). Du Fu\'s lines "\u6BCF\u4F9D\u5317\u6597\u671B\u4EAC\u534E" ("Always gazing toward the capital by the light of the Big Dipper") and "\u5317\u6781\u671D\u5EF7\u7EC8\u4E0D\u6539" ("The North Star court shall never change") are perhaps the most literary expressions of this Great Savior imagery. Of course, compared to Du Fu\'s own "\u9526\u6C5F\u6625\u8272\u6765\u5929\u5730\uFF0C\u7389\u5792\u6D6E\u4E91\u53D8\u53E4\u4ECA" ("The spring colors of the Brocade River span heaven and earth; the floating clouds of Jade Fortress transform ancient and modern"), those lines fall short by N to the Nth power of North Stars.'}),"\n",(0,n.jsx)(t.p,{children:"The Great Savior \u2014 a human's game in a society that does not believe in gods \u2014 even with the directional sense of the North Star added, would probably be nothing more than a joke (of people who don't even believe in gods) in the eyes of Engels, who equally did not believe in gods. Engels had an excellent metaphor for the direction of human social development. Simply put: each person's movement constitutes a vector, and the superposition of all vectors constitutes the resultant vector \u2014 that direction being the direction of human social development. Since every person is constantly changing \u2014 that is, every component constituting the resultant vector of social development is a variable \u2014 for one component or some combination of components to always equal the resultant vector of social development is something probably even God wouldn't hope to accomplish, unless someone is more foolish than God himself."}),"\n",(0,n.jsx)(t.p,{children:"Setting aside the above mathematical analysis, the progress of science has already made the following conclusion common knowledge: even \"permanent\" stars are not actually permanent. Therefore, the North Star literary image of the Great Savior shall forever remain just a literary image. The Great Savior \u2014 a savior more savior than the Savior himself! The Messiah merely represents humanity's fear and delusion; a savior more savior than the Savior is merely the superposition of the same joke. There is no savior in this world, and even less a Great Savior. What exists is only the resultant direction of social development constituted by each person's development and change superimposed \u2014 on this point, Engels needed no literary imagination. And this, of course, is not merely because he was a Westerner who did not believe in God!"})]})}function s(e={}){let{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,n.jsx)(t,{...e,children:(0,n.jsx)(r,{...e})}):r(e)}},37973(e,t,o){o.r(t),o.d(t,{metadata:()=>n,default:()=>u,frontMatter:()=>s,contentTitle:()=>h,toc:()=>c,assets:()=>l});var n=JSON.parse('{"id":"timeline/confucius/20060418","title":"","description":"","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/timeline/confucius/20060418.md","sourceDirName":"timeline/confucius","slug":"/timeline/confucius/20060418","permalink":"/en/timeline/confucius/20060418","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"20060418","title":"","hide_table_of_contents":true,"sidebar_label":"The Great Savior: A Savior More Savior-Like Than the Savior Himself! (2006/4/18 21:29:10)"},"sidebar":"timelineSidebar","previous":{"title":"Castrated Pseudo-Comprehensiveness! (2006/4/17 16:55:57)","permalink":"/en/timeline/confucius/20060417"},"next":{"title":"Bush: The Great Savior of Today\'s World! (2006/4/19 21:42:50)","permalink":"/en/timeline/confucius/20060419"}}'),i=o(74848),a=o(28453),r=o(1573);let s={id:0x1321902,title:"",hide_table_of_contents:!0,sidebar_label:"The Great Savior: A Savior More Savior-Like Than the Savior Himself! (2006/4/18 21:29:10)"},h,l={},c=[...r.RM];function d(e){return(0,i.jsx)(r.Ay,{})}function u(e={}){let{wrapper:t}={...(0,a.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(d,{...e})}):d(e)}},28453(e,t,o){o.d(t,{R:()=>r,x:()=>s});var n=o(96540);let i={},a=n.createContext(i);function r(e){let t=n.useContext(a);return n.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function s(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:r(e.components),n.createElement(a.Provider,{value:t},e.children)}}}]);